source='''def transform(grid):
    height, width = len(grid), len(grid[0])
    cells = {(r, c) for r in range(height) for c in range(width) if grid[r][c] != 0}
    components = []
    unseen = set(cells)
    while unseen:
        start = min(unseen)
        color = grid[start[0]][start[1]]
        stack = [start]
        unseen.remove(start)
        component = {start}
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in unseen and grid[nr][nc] == color:
                    unseen.remove((nr,nc))
                    component.add((nr,nc))
                    stack.append((nr,nc))
        components.append((color, component))

    # Let rightmost objects move first; repeat so trailing objects can follow blockers.
    moved = True
    while moved:
        moved = False
        components.sort(key=lambda item: max(c for _, c in item[1]), reverse=True)
        occupied = {pos for _, comp in components for pos in comp}
        for color, comp in components:
            while True:
                shifted = {(r, c + 1) for r, c in comp}
                if any(c >= width for _, c in shifted):
                    break
                if any(pos in occupied and pos not in comp for pos in shifted):
                    break
                occupied.difference_update(comp)
                occupied.update(shifted)
                comp.clear()
                comp.update(shifted)
                moved = True
    output = [[0] * width for _ in range(height)]
    for color, comp in components:
        for r, c in comp:
            output[r][c] = color
    return output
'''
